from pathlib import Path
p=[]
for line in Path('graphene.dat').read_text().splitlines():
    try: p.append(tuple(map(float,line.replace(',','.').split()[:2])))
    except: pass
# Sort by x for smoothing/rank diagnostics.
p=sorted(p)
x=[a for a,b in p]; y=[b for a,b in p]
# Moving-average extrema using several window sizes.
for w in (5,11,21):
    z=[]
    for i in range(len(y)):
        lo=max(0,i-w//2); hi=min(len(y),i+w//2+1); z.append(sum(y[lo:hi])/(hi-lo))
    inds=sorted(sorted(range(len(z)),key=z.__getitem__,reverse=True)[:30])
    print('\nwindow',w,'top smoothed candidates:')
    out=[]
    for i in inds:
        # Keep one candidate per 20-point neighborhood.
        if all(abs(x[i]-x[j])>20 for j in out): out.append(i)
    for i in out[:15]: print(f'x={x[i]:10.3f} raw={y[i]:10.2f} smooth={z[i]:10.2f}')
